create_delivery_group.afterResponse:
const wanted = inputs.name.trim().toLowerCase();
const matching = (answer) => ((answer && answer.groups) || []).find((group) => group.name.trim().toLowerCase() === wanted);
const existing = matching(response);
if (existing !== undefined) return { group: existing.group, name: existing.name, created: false };
try {
  return { group: call({ method: 'POST', url: '/groups.json', body: { name: inputs.name } }).group, name: inputs.name, created: true };
} catch (error) {
  const message = String((error && error.message) || error);
  const status = /status (\d+)/.exec(message);
  if ((status && Number(status[1]) >= 500) || !/already (exists|been taken|in use)|has already been|must be unique/i.test(message)) throw error;
  const raced = matching(call({ method: 'GET', url: request.url }));
  if (raced === undefined) throw error;
  return { group: raced.group, name: raced.name, created: false };
}
